using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace StarterAssets.CQCEditorTools
{
 [InitializeOnLoad]public static class CastleGrassDirtFlowerBeds
 {
  const string Request="Assets/Editor/CQC/CastleGrassDirtFlowerBeds.request.txt";static double next;
  static CastleGrassDirtFlowerBeds(){EditorApplication.update+=Pending;}
  static void Pending(){if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+1;if(!File.Exists(Request)||EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||SceneManager.GetActiveScene().name!="MyForest")return;Undo.IncrementCurrentGroup();int group=Undo.GetCurrentGroup();try{Apply();Undo.CollapseUndoOperations(group);AssetDatabase.DeleteAsset(Request);}catch(Exception e){Undo.RevertAllDownToGroup(group);Directory.CreateDirectory("Logs");File.WriteAllText("Logs/CastleGrassDirtFlowerBeds-error.txt",e.ToString());Debug.LogException(e);AssetDatabase.MoveAsset(Request,Request+"."+DateTime.Now.ToString("yyyyMMddHHmmss")+".failed");}}
  [MenuItem("Tools/City/Add Side By Side Grass Dirt Beds And Flowers")]
  public static void Apply()
  {
   var mountain=GameObject.Find("Castle Mountain");if(!mountain)throw new InvalidOperationException("Castle missing.");if(mountain.transform.Find("Side By Side Castle Flower Gardens"))return;var gardens=mountain.transform.Find("Courtyard Gardens On Both Sides");var roads=mountain.transform.Find("Connected Castle Stone Roads");if(!gardens||!roads)throw new InvalidOperationException("Castle garden and roads required.");var floor=mountain.transform.Find("Inner Castle Mountain/Flat Inner Castle Floor").GetComponent<MeshCollider>();var shrubs=gardens.GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("Courtyard Boxwood",StringComparison.Ordinal)&&t.gameObject.activeInHierarchy).ToArray();
   const string nature="Assets/InnerverseInteractive/Ultimate Nature – Starter/Environment/";var grass=AssetDatabase.LoadAssetAtPath<TerrainLayer>(nature+"Terrain/Layers/UNS_Grass.terrainlayer");var dirt=AssetDatabase.LoadAssetAtPath<TerrainLayer>(nature+"Terrain/Layers/UNS_Dirt.terrainlayer");var flower=AssetDatabase.LoadAssetAtPath<GameObject>(nature+"Vegetation/Flowers/Prefabs/UNS_Flower.prefab");if(!grass||!dirt||!flower)throw new InvalidOperationException("Original UNS grass, dirt or flowers missing.");
   var original=mountain.GetComponentsInChildren<Transform>(true);var matrices=original.Select(t=>t.localToWorldMatrix).ToArray();var roadPolys=new List<Vector2[]>();foreach(var f in roads.GetComponentsInChildren<MeshFilter>()){var v=f.sharedMesh.vertices;var ids=f.sharedMesh.triangles;for(int i=0;i<ids.Length;i+=3)roadPolys.Add(new[]{Flat(f.transform.TransformPoint(v[ids[i]])),Flat(f.transform.TransformPoint(v[ids[i+1]])),Flat(f.transform.TransformPoint(v[ids[i+2]]))});}
   var scene=SceneManager.GetActiveScene();string stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss"),backup="Assets/ForestExpansion/Backups/MyForest-before-grass-dirt-flower-beds-"+stamp+".unity";if(!EditorSceneManager.SaveScene(scene,backup,true))throw new IOException("Backup failed.");string folder="Assets/CityExpansion/CastleFlowerBeds-"+stamp;Directory.CreateDirectory(folder);AssetDatabase.Refresh();var gm=Material(grass,"Original Green Grass Beds",folder);var dm=Material(dirt,"Original Brown Dirt Beds",folder);
   var root=new GameObject("Side By Side Castle Flower Gardens");root.transform.SetParent(mountain.transform,false);Undo.RegisterCreatedObjectUndo(root,"Add side by side garden beds and flowers");var gv=new List<Vector3>();var dv=new List<Vector3>();int beds=0,flowers=0,skipped=0;float ground=floor.bounds.max.y+.03f;
   foreach(var shrub in shrubs)
   {
    var b=BoundsOf(shrub.gameObject);Vector3 center=b.center;center.y=ground;var right=Vector3.ProjectOnPlane(shrub.right,Vector3.up).normalized;var forward=Vector3.ProjectOnPlane(shrub.forward,Vector3.up).normalized;float width=4.9f,length=3.5f;var corners=new[]{center-right*width*.5f-forward*length*.5f,center+right*width*.5f-forward*length*.5f,center+right*width*.5f+forward*length*.5f,center-right*width*.5f+forward*length*.5f};
    // Keep existing paths visible; a smaller bed fits tighter landscaped sections.
    bool accepted=false;foreach(float margin in new[]{0f,.35f,.55f}){float w=width-margin,l=length-margin;corners=new[]{center-right*w*.5f-forward*l*.5f,center+right*w*.5f-forward*l*.5f,center+right*w*.5f+forward*l*.5f,center-right*w*.5f+forward*l*.5f};var polygon=corners.Select(Flat).ToArray();if(roadPolys.Any(p=>Intersects(polygon,p)))continue;if(!corners.All(p=>floor.Raycast(new Ray(p+Vector3.up*10,Vector3.down),out RaycastHit hit,20)))continue;width=w;length=l;accepted=true;break;}if(!accepted){skipped++;continue;}
    Vector3 back=center-forward*length*.5f,front=center+forward*length*.5f;AddQuad(root.transform,new[]{back-right*width*.5f,back,front,front-right*width*.5f},gv);AddQuad(root.transform,new[]{back,back+right*width*.5f,front+right*width*.5f,front},dv);beds++;
    var lot=new GameObject(shrub.name+" Flower Border");lot.transform.SetParent(root.transform,false);for(int i=0;i<6;i++)
    {
     Vector3 spot=center+right*(width*.5f-.14f)+forward*Mathf.Lerp(-length*.42f,length*.42f,(i+.5f)/6);var go=(GameObject)PrefabUtility.InstantiatePrefab(flower);go.transform.SetParent(lot.transform,true);go.transform.rotation=Quaternion.Euler(0,(i*53+beds*31)%360,0);var fb=BoundsOf(go);go.transform.localScale*=.38f/Mathf.Max(.001f,fb.size.y);fb=BoundsOf(go);go.transform.position+=new Vector3(spot.x-fb.center.x,ground+.01f-fb.min.y,spot.z-fb.center.z);go.name="Garden Flowers "+(++flowers).ToString("000");foreach(var c in go.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);PrefabUtility.RecordPrefabInstancePropertyModifications(go.transform);
    }
   }
   if(beds==0)throw new InvalidOperationException("No safe garden bed space beside current shrubs; scene retained.");Save(root.transform,gv,gm,grass.tileSize,"Green Grass Strips",folder+"/GrassBeds.asset");Save(root.transform,dv,dm,dirt.tileSize,"Brown Dirt Flower Strips",folder+"/DirtBeds.asset");for(int i=0;i<original.Length;i++)if(original[i].localToWorldMatrix!=matrices[i])throw new InvalidOperationException("Existing model moved; garden addition rolled back.");AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new IOException("Save failed.");SceneView.RepaintAll();Directory.CreateDirectory("Logs");File.WriteAllText("Logs/CastleGrassDirtFlowerBeds-report.txt","Added "+beds+" small garden beds, each with original UNS green grass and brown dirt in separate side-by-side strips, alongside existing thick castle bushes. Added "+flowers+" original UNS flower clusters along the visible dirt border. Skipped "+skipped+" tight sections to preserve road surfaces. Bed corners checked on existing castle floor; new surface overlays only, without new blocking colliders. Existing plants, roads, buildings and global terrain texture blend retained.\nBackup: "+backup);Debug.Log("Side-by-side grass and dirt castle gardens with flowers added. Scene saved.");
  }
  static Material Material(TerrainLayer layer,string name,string folder){var m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name=name};m.SetTexture("_BaseMap",layer.diffuseTexture);m.SetColor("_BaseColor",Color.white);m.SetFloat("_Smoothness",.05f);if(layer.normalMapTexture){m.SetTexture("_BumpMap",layer.normalMapTexture);m.SetFloat("_BumpScale",.5f);m.EnableKeyword("_NORMALMAP");}m.enableInstancing=true;AssetDatabase.CreateAsset(m,folder+"/"+name.Replace(" ","")+".mat");return m;}
  static void AddQuad(Transform parent,Vector3[] corners,List<Vector3> vertices){foreach(var p in corners)vertices.Add(parent.InverseTransformPoint(p));}
  static void Save(Transform parent,List<Vector3> vertices,Material material,Vector2 tile,string name,string path){var ids=new List<int>();var uv=new List<Vector2>();for(int i=0;i<vertices.Count;i++){var w=parent.TransformPoint(vertices[i]);uv.Add(new Vector2(w.x/Mathf.Max(.1f,tile.x),w.z/Mathf.Max(.1f,tile.y)));}for(int i=0;i<vertices.Count;i+=4){Vector3 n=Vector3.Cross(vertices[i+1]-vertices[i],vertices[i+2]-vertices[i]);if(parent.TransformDirection(n).y>0)ids.AddRange(new[]{i,i+1,i+2,i,i+2,i+3});else ids.AddRange(new[]{i,i+2,i+1,i,i+3,i+2});}var mesh=new Mesh{name=name};mesh.SetVertices(vertices);mesh.SetUVs(0,uv);mesh.SetTriangles(ids,0);mesh.RecalculateNormals();mesh.RecalculateTangents();mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,path);var go=new GameObject(name);go.transform.SetParent(parent,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=material;}
  static Vector2 Flat(Vector3 p){return new Vector2(p.x,p.z);}
  static bool Intersects(Vector2[] a,Vector2[] b){foreach(var polygon in new[]{a,b})for(int i=0;i<polygon.Length;i++){var edge=polygon[(i+1)%polygon.Length]-polygon[i];if(edge.sqrMagnitude<.00001f)continue;var axis=new Vector2(-edge.y,edge.x).normalized;float amin=float.PositiveInfinity,amax=float.NegativeInfinity,bmin=amin,bmax=amax;foreach(var p in a){float v=Vector2.Dot(axis,p);amin=Mathf.Min(amin,v);amax=Mathf.Max(amax,v);}foreach(var p in b){float v=Vector2.Dot(axis,p);bmin=Mathf.Min(bmin,v);bmax=Mathf.Max(bmax,v);}if(amax<bmin||bmax<amin)return false;}return true;}
  static Bounds BoundsOf(GameObject go){var r=go.GetComponentsInChildren<Renderer>();var b=r[0].bounds;foreach(var part in r)b.Encapsulate(part.bounds);return b;}
 }
}
